    "\u7ed9\u4f60\u4e00\u4e2a\u7531\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\uff08'a' \u5230 'z'\uff09\u7ec4\u6210\u7684\u5b57\u7b26\u4e32 s\u3002\u4f60\u7684\u4efb\u52a1\u662f\u627e\u51fa\u51fa\u73b0\u9891\u7387\u00a0\u6700\u9ad8\u00a0\u7684\u5143\u97f3\uff08'a'\u3001'e'\u3001'i'\u3001'o'\u3001'u' \u4e2d\u7684\u4e00\u4e2a\uff09\u548c\u51fa\u73b0\u9891\u7387\u6700\u9ad8\u7684\u8f85\u97f3\uff08\u9664\u5143\u97f3\u4ee5\u5916\u7684\u6240\u6709\u5b57\u6bcd\uff09\uff0c\u5e76\u8fd4\u56de\u8fd9\u4e24\u4e2a\u9891\u6570\u4e4b\u548c\u3002\n\n\u6ce8\u610f\uff1a\u5982\u679c\u6709\u591a\u4e2a\u5143\u97f3\u6216\u8f85\u97f3\u5177\u6709\u76f8\u540c\u7684\u6700\u9ad8\u9891\u7387\uff0c\u53ef\u4ee5\u4efb\u9009\u5176\u4e2d\u4e00\u4e2a\u3002\u5982\u679c\u5b57\u7b26\u4e32\u4e2d\u6ca1\u6709\u5143\u97f3\u6216\u6ca1\u6709\u8f85\u97f3\uff0c\u5219\u5176\u9891\u7387\u89c6\u4e3a 0\u3002\n\n\u4e00\u4e2a\u5b57\u6bcd x \u7684\u00a0\u9891\u7387\u00a0\u662f\u5b83\u5728\u5b57\u7b26\u4e32\u4e2d\u51fa\u73b0\u7684\u6b21\u6570\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n\u8f93\u5165: s = \"successes\"\n\n\u8f93\u51fa: 6\n\n\u89e3\u91ca:\n\n\t\u5143\u97f3\u6709\uff1a'u' \u51fa\u73b0 1 \u6b21\uff0c'e' \u51fa\u73b0 2 \u6b21\u3002\u6700\u5927\u5143\u97f3\u9891\u7387 = 2\u3002\n\n\t\u8f85\u97f3\u6709\uff1a's' \u51fa\u73b0 4 \u6b21\uff0c'c' \u51fa\u73b0 2 \u6b21\u3002\u6700\u5927\u8f85\u97f3\u9891\u7387 = 4\u3002\n\n\t\u8f93\u51fa\u4e3a 2 + 4 = 6\u3002\n\n\u793a\u4f8b 2\uff1a\n\n\u8f93\u5165: s = \"aeiaeia\"\n\n\u8f93\u51fa: 3\n\n\u89e3\u91ca:\n\n\t\u5143\u97f3\u6709\uff1a'a' \u51fa\u73b0 3 \u6b21\uff0c'e' \u51fa\u73b0 2 \u6b21\uff0c'i' \u51fa\u73b0 2 \u6b21\u3002\u6700\u5927\u5143\u97f3\u9891\u7387 = 3\u3002\n\n\ts \u4e2d\u6ca1\u6709\u8f85\u97f3\u3002\u56e0\u6b64\uff0c\u6700\u5927\u8f85\u97f3\u9891\u7387 = 0\u3002\n\n\t\u8f93\u51fa\u4e3a 3 + 0 = 3\u3002\n\n\u00a0\n\n\u63d0\u793a:\n\n\t1 <= s.length <= 100\n\n\ts \u53ea\u5305\u542b\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nfrom collections import Counter\n\nclass Solution:\n    def maxFreqSum(self, s: str) -> int:\n        mp = Counter(s)\n        vowel = max((mp[ch] for ch in mp if ch in \"aeiou\"), default=0)\n        consonant = max((mp[ch] for ch in mp if ch not in \"aeiou\"), default=0)\n        return vowel + consonant\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxFreqSum(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
